"""Capture exactly the maintained inputs that the current acceptance exercises."""
import hashlib
import json
from pathlib import Path
import sys

root = Path(__file__).resolve().parent
previous = json.loads((root / 'coverage-audit-25.4.12.json').read_bytes())
proof = json.loads((root / 'identity.json').read_bytes())
assets = Path('skills/ax-skills')
paths = set(previous['current']['file_hashes'])
paths.update(str(x) for x in (assets/'examples').glob('[0-9][0-9]-*.ts'))
paths.update(('scripts/sync_ax_sources.py', 'scripts/validate_ax_skills.py', 'scripts/test_sync_ax_sources.py', 'scripts/test_validate_ax_skills.py', 'SKILLS_SPEC.md'))


def sha(data):
    return hashlib.sha256(data).hexdigest()


def entry(p):
    b = Path(p).read_bytes()
    return {'sha256': sha(b), 'bytes': len(b), 'lines': len(b.splitlines())}


source = {}
for row in proof['fixture_inputs'][proof['user_import']]:
    p = row['path']
    actual = entry(p)
    assert actual == {k: v for k, v in row.items() if k != 'path'}, f'moved admitted source {p}'
    source[p] = actual
files = {p: entry(p) for p in sorted(paths)}
execution = {p: x for p, x in files.items() if p.startswith('skills/ax-skills/examples/') and not p.endswith('.md')}
record = {'files': files, 'sources': source, 'execution_inputs': execution}
blob = (json.dumps(record, indent=2, sort_keys=True)+'\n').encode()
if len(sys.argv) == 2:
    before = Path(sys.argv[1]).read_bytes()
    assert before == blob, 'source, curated or executable input moved during acceptance'
sys.stdout.buffer.write(blob)

