import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const entry = resolve('skills/ax-skills/examples');
const { AxDockerSession, AxEvalUtil, AxAIDeepSeekModel } = await import(pathToFileURL(resolve(entry, 'node_modules/@ax-llm/ax/index.js')));
const cjs = createRequire(resolve(entry, 'package.json'))('@ax-llm/ax');
assert.equal(cjs.AxAIDeepSeekModel.DeepSeekFlash, AxAIDeepSeekModel.DeepSeekFlash);
assert.equal(AxAIDeepSeekModel.DeepSeekFlash, 'deepseek-flash');
const ordinaryF1 = AxEvalUtil.f1Score('the record record', 'the record');
const novelF1 = AxEvalUtil.novelF1ScoreOptimized('', 'the record record', 'the record');
assert.equal(ordinaryF1, 0.8);
assert.ok(Math.abs(novelF1 - 2 / 3) < Number.EPSILON);
assert.equal(AxEvalUtil.f1Score('constructor', 'constructor'), 1);
assert.equal(cjs.AxEvalUtil.f1Score('the record record', 'the record'), ordinaryF1);

// A fake HTTP peer at the fetch boundary: no Docker socket, daemon or network.
const calls = [];
const actualFetch = globalThis.fetch;
let pullBody = '{"status":"done"}\n';
try {
  globalThis.fetch = async (input, options) => {
    const url = new URL(input);
    assert.equal(url.origin, 'https://fixture.invalid');
    calls.push([options?.method ?? 'GET', url.pathname, url.search]);
    switch (url.pathname) {
      case '/containers/json':
        return Response.json([
          { Id: 'running', State: 'running', Labels: { 'com.example.tag': 'sprint-owned' } },
          { Id: 'stopped', State: 'exited', Labels: { 'com.example.tag': 'sprint-owned' } },
          { Id: 'foreign', State: 'running', Labels: { 'com.example.tag': 'foreign' } },
        ]);
      case '/containers/running/stop': return new Response(null, { status: 204 });
      case '/images/create': return new Response(pullBody, { status: 200 });
      default: throw new Error(`Unexpected fixture path ${url.pathname}`);
    }
  };
  const session = new AxDockerSession('https://fixture.invalid');
  assert.deepEqual(await session.stopContainers({ tag: 'sprint-owned', timeout: 3 }), [{ Id: 'running', Action: 'stopped' }]);
  assert.deepEqual(calls.slice(0, 2), [['GET', '/containers/json', '?all=true'], ['POST', '/containers/running/stop', '?t=3']]);
  await session.pullImage('example/asset:fixture');
  pullBody = '{"status":"downloading"}\n\n{"error":"legacy text","errorDetail":{"message":"fixture pull denied"}}\n';
  await assert.rejects(session.createContainer({ imageName: 'example/asset:fixture' }), /Failed to pull image: fixture pull denied/);
  assert.equal(calls.length, 4);
  assert.equal(calls.at(-1)[1], '/images/create');
} finally {
  globalThis.fetch = actualFetch;
}
console.log(JSON.stringify({ ordinaryF1, novelF1, cjsExportsChecked: true, dockerSyntheticCalls: calls, imageCreateAfterFailedPull: false, remoteHTTP: 0 }));

