import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { readFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';

const entry = resolve('skills/ax-skills/examples');
const ts = createRequire(resolve(entry, 'package.json'))('typescript');
const hash = (text) => createHash('sha256').update(text).digest('hex');
const baseline = process.argv[2];
const rows = {};
for (const module of readdirSync(entry).filter(name => /^\d{2}-.+\.ts$/.test(name)).sort()) {
  const content = baseline
    ? execFileSync('git', ['show', `${baseline}:skills/ax-skills/examples/${module}`], { encoding: 'utf8' })
    : readFileSync(resolve(entry, module), 'utf8');
  const source = ts.createSourceFile(module, content, ts.ScriptTarget.Latest, true);
  assert.deepEqual(source.parseDiagnostics, [], module);
  const line = (offset) => source.getLineAndCharacterOfPosition(offset).line + 1;
  const visit = (node) => {
    if (ts.isObjectLiteralExpression(node)) {
      const id = node.properties.find((p) => ts.isPropertyAssignment(p) && p.name.getText(source) === 'id')?.initializer;
      const run = node.properties.find(p => (ts.isMethodDeclaration(p) || ts.isPropertyAssignment(p)) && p.name.getText(source) === 'run');
      if (id && ts.isStringLiteral(id) && id.text.startsWith(`${module.slice(0, -3)}/`) && run) {
        const start = node.getStart(source), end = node.getEnd();
        assert(!(id.text in rows), id.text);
        rows[id.text] = {
          file: `examples/${module}`, case_span: [line(start), line(end)], case_body_sha256: hash(content.slice(start, end)),
          run_sha256: hash(run.getText(source)),
        };
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(source);
}
console.log(JSON.stringify(rows));

