"""Read-only check of existing native Beads containment and prerequisite records."""
import collections
import json
import subprocess
import sys

root = 'ax-skills-b6v'

def bd(*args):
    return json.loads(subprocess.check_output(('bd', '--sandbox', *args, '--json')))

all_issues = bd('list','--all','--brief','--limit','0')
issues = {x['id']: {'status': x['status'], 'type': x['issue_type'], 'title': x['title']} for x in all_issues if x['id'] == root or x['id'].startswith(root+'.')}
assert issues[root]['type'] == 'epic'
l1 = {i for i in issues if i.count('.') == 1 and issues[i]['type'] == 'epic'}
l2 = {i for i in issues if i.count('.') == 2 and issues[i]['type'] == 'task'}
assert len(l1) == 5 and len(issues) == 1 + len(l1) + len(l2), list(issues)
assert all(i.rpartition('.')[0] in l1 for i in l2)
edges = bd('dep','list',*sorted(issues),'--type','blocks')
deps = collections.defaultdict(set)
for edge in edges:
    prerequisite, consumer = edge['depends_on_id'], edge['issue_id']
    assert edge['type'] == 'blocks' and prerequisite in l2 and consumer in l2, edge
    assert not (prerequisite.startswith(consumer+'.') or consumer.startswith(prerequisite+'.')), edge
    assert prerequisite not in deps[consumer], edge
    deps[consumer].add(prerequisite)
visited, visiting = set(), set()
def visit(i):
    assert i not in visiting, f'cycle at {i}'
    if i in visited:
        return
    visiting.add(i)
    for pre in deps[i]: visit(pre)
    visiting.remove(i)
    visited.add(i)
for i in issues: visit(i)
if '--accepted' in sys.argv:
    publication = {root,root+'.5',*(i for i in l2 if i.startswith(root+'.5.'))}
    assert all(data['status'] == 'closed' for i, data in issues.items() if i not in publication), issues
elif '--published' in sys.argv:
    assert all(i['status'] == 'closed' for i in issues.values()), issues
print(json.dumps({'root':root,'l1':len(l1),'l2':len(l2),'count':len(issues),'edges':len(edges),'issues':issues,'prerequisites':{k:sorted(v) for k,v in deps.items() if v},'cycles':0,'ancestor_blockers':0},indent=2))

