import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

// The ordinary CLI intentionally suppresses SDK errors. Use this only on a
// named failing offline fixture, with the same public scripts and no secrets.
const base = resolve('skills/ax-skills/examples');
const originalFetch = globalThis.fetch;
const fetch = (input, init) => {
  const url = new URL(input instanceof Request ? input.url : input);
  if (!['127.0.0.1', '::1', '[::1]', 'localhost'].includes(url.hostname)) {
    throw new Error(`Non-loopback HTTP is disabled for offline diagnostics: ${url.origin}`);
  }
  return originalFetch(input, { ...init, redirect: 'error' });
};
globalThis.fetch = fetch;
try {
  for (const name of process.argv.slice(2)) {
    const module = name.split('/')[0];
    const imported = await import(pathToFileURL(resolve(base, `${module}.ts`)));
    const cases = imported.examples ?? Object.values(imported).find(Array.isArray);
    const selected = cases.filter(item => item.id === name && item.modes.includes('offline'));
    if (selected.length !== 1) throw new Error(`Expected one named offline case ${name}`);
    const signal = AbortSignal.timeout(25_000);
    const ctx = { mode: 'offline', signal, fetch,
      get ai() { throw new Error('Live AI forbidden'); },
      get decisions() { throw new Error('Live decision AI forbidden'); },
      get nativeDecisions() { throw new Error('Live native decisions forbidden'); },
    };
    try {
      const result = await selected[0].run(ctx);
      console.log(JSON.stringify({ id: name, result }));
    } catch (error) {
      console.error(name, error);
      process.exitCode = 1;
    }
  }
} finally {
  globalThis.fetch = originalFetch;
}
